entries[22389] = { ["name"] = "Plans: Sageblade", ["text"] = "Requires Blacksmithing (300)\nRequires Master Swordsmith\n\nUse: Teaches you how to make a Sageblade.\nSell Price:\nSageblade\nBinds when equipped\nMain Hand Sword\n49 - 100 Damage Speed 1.80\n(41.39 damage per second)\n+14 Stamina\n+6 Intellect\nDurability 105 / 105\nRequires Level 59\nEquip: Increases damage and healing done by magical spells and effects by up to 20.\n\nEquip: Decreases the magical resistances of your spell targets by 10.\nSell Price:\nRequires Arcanite Bar (12), Nexus Crystal (2), Flask of Supreme Power (2), Enchanted Leather (4)" }
entries[22390] = { ["name"] = "Plans: Persuader", ["text"] = "Requires Blacksmithing (300)\nRequires Master Hammersmith\n\nUse: Teaches you how to make the Persuader.\nSell Price:\nPersuader\nBinds when equipped\nMain Hand Mace\n86 - 161 Damage Speed 2.70\n(45.74 damage per second)\nDurability 105 / 105\nRequires Level 58\nEquip: Improves your chance to hit by 1%.\n\nEquip: Improves your chance to get a critical strike by 1%.\nSell Price:\nRequires Arcanite Bar (15), Dark Iron Bar (10), Essence of Undeath (20), Dark Rune (20), Devilsaur Leather (10), Skin of Shadow (2)" }
entries[22392] = { ["name"] = "Formula: Enchant 2H Weapon - Agility", ["text"] = "Binds when picked up\nRequires Enchanting (290)\nRequires Timbermaw Hold\n- Friendly\n\nUse: Teaches you how to permanently enchant a two-handed weapon to increase your agility by 25.\nSell Price:" }
